-- #176 지급 전 판정 정정 (ADR-0093 decision 1 #173 items 1, 2, 5, 7, 8 and 13, decision 3 '#176
-- 정정 대기', the owner's answer of 2026-11-02; ADR-0105). Generated by `drizzle-kit generate`,
-- then hand-edited where marked: this header and the tail. The snapshot is as generated.
--
-- - market_judgements.correction_reason: the 정정 사유 of a version a correction made — exactly
--   for a version after the first, trimmed, 1–500 (as market_rule_versions.reason). ADD COLUMN
--   writes no row (the keep-record trigger does not fire), and the CHECK holds on every existing
--   row: only v1s exist before this migration, with no reason.
-- - market_disputes.closed_at: when the approval of a correction that replaced its version
--   closed a pending dispute (status `closed_by_correction` 정정으로 종결, #173 item 8 — exactly 20
--   characters, the column's limit), exactly for that status and never before the submission
--   (market_disputes_closed_check). The status CHECK takes the new value (the generated drop and
--   add: the list follows MARKET_DISPUTE_STATUSES of @buddha/shared); the 처리됨 index and the
--   purge CHECK read the closure as the end it is (coalesce(decided_at, retracted_at,
--   closed_at), the reader's key). Null on every existing row: nothing was closed before.
-- - markets.correction_pending: whether a correction of the current version waits for its
--   decision, mirrored for the label '판정 지연' past the deadline (#173 item 11) and written under
--   the market lock by the @buddha/db judgement writers; false on a market that is not
--   PROVISIONAL (markets_correction_pending_status_check). False on every existing row: no
--   correction was registered before this migration. The hold itself is the waiting
--   `market_judgement` request (confirmationHold), read by approval_requests' indexes (no new one).
-- - The keep-record trigger of market_disputes, replaced (below): a pending dispute also takes
--   `closed_by_correction`, and an accepted one goes back to pending when the correction
--   registered for it is rejected or retracted (owner answer 2026-11-02).
-- - No new table, type, approval kind or release setting: the event type `judgement_corrected`
--   and the correction's admin actions (the four `market_judgement_*`) are varchar values
--   (@buddha/shared), and a correction is a `market_judgement` request with its `correction`.
ALTER TABLE "market_disputes" DROP CONSTRAINT "market_disputes_status_check";--> statement-breakpoint
ALTER TABLE "market_disputes" DROP CONSTRAINT "market_disputes_purged_check";--> statement-breakpoint
DROP INDEX "market_disputes_ended_at_idx";--> statement-breakpoint
ALTER TABLE "market_disputes" ADD COLUMN "closed_at" timestamp (3) with time zone;--> statement-breakpoint
ALTER TABLE "market_judgements" ADD COLUMN "correction_reason" text;--> statement-breakpoint
ALTER TABLE "markets" ADD COLUMN "correction_pending" boolean DEFAULT false NOT NULL;--> statement-breakpoint
CREATE INDEX "market_disputes_ended_at_idx" ON "market_disputes" USING btree (coalesce("decided_at", "retracted_at", "closed_at"),"id") WHERE "market_disputes"."status" <> 'pending';--> statement-breakpoint
ALTER TABLE "market_disputes" ADD CONSTRAINT "market_disputes_closed_check" CHECK (("market_disputes"."status" = 'closed_by_correction') = ("market_disputes"."closed_at" IS NOT NULL) AND ("market_disputes"."closed_at" IS NULL OR "market_disputes"."closed_at" >= "market_disputes"."submitted_at"));--> statement-breakpoint
ALTER TABLE "market_disputes" ADD CONSTRAINT "market_disputes_status_check" CHECK ("market_disputes"."status" IN ('pending', 'dismissed', 'accepted', 'retracted', 'closed_by_correction'));--> statement-breakpoint
ALTER TABLE "market_disputes" ADD CONSTRAINT "market_disputes_purged_check" CHECK ("market_disputes"."purged_at" IS NULL OR ("market_disputes"."status" <> 'pending' AND "market_disputes"."purged_at" >= coalesce("market_disputes"."decided_at", "market_disputes"."retracted_at", "market_disputes"."closed_at")));--> statement-breakpoint
ALTER TABLE "market_judgements" ADD CONSTRAINT "market_judgements_correction_reason_check" CHECK (("market_judgements"."version" = 1) = ("market_judgements"."correction_reason" IS NULL) AND ("market_judgements"."correction_reason" IS NULL OR (btrim("market_judgements"."correction_reason") <> '' AND char_length("market_judgements"."correction_reason") <= 500)));--> statement-breakpoint
ALTER TABLE "markets" ADD CONSTRAINT "markets_correction_pending_status_check" CHECK (NOT "markets"."correction_pending" OR "markets"."status" = 'provisional');--> statement-breakpoint
-- Hand-edited: market_disputes_keep_record (migration 0056) replaced in place — the trigger stays,
-- the function changes. An UPDATE either (a) moves a dispute along MARKET_DISPUTE_TRANSITIONS:
-- a pending one to dismissed, accepted, retracted or closed_by_correction (#176: a correction's
-- approval closes the replaced version's pending disputes, #173 item 8), or an accepted one back
-- to pending (#176: the correction registered for it rejected or retracted, owner answer
-- 2026-11-02 — its decision cleared, which market_disputes_decision_check holds, and never one
-- the retention emptied), with what the submission recorded (the id, the judgement, the
-- submitter, the links, the reason and the submission instant) unchanged and the CHECKs holding
-- each status's columns; or (b) is the retention's: `purged_at` from null to a value, the links
-- and the reason emptied ('{}', ''), every other column — `closed_at` now among them — as it
-- was, once, and only of an ended dispute (market_disputes_purged_check). Which disputes a
-- correction closes or reopens (the replaced version's pending ones; the request's accepted ones
-- still on the current version) is @buddha/db's, in the transaction that moves the version or
-- decides the request: the order of those writes is what a trigger here could not see.
CREATE OR REPLACE FUNCTION market_disputes_keep_record() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'dispute % of market % is a permanent record and takes no DELETE', OLD.id,
      OLD.market_id
      USING ERRCODE = 'integrity_constraint_violation';
  END IF;
  IF OLD.purged_at IS NULL AND NEW.purged_at IS NOT NULL THEN
    IF NEW.links <> '{}' OR NEW.reason <> ''
       OR (NEW.id, NEW.market_id, NEW.judgement_version, NEW.user_id, NEW.status,
           NEW.submitted_at, NEW.decided_by, NEW.decided_at, NEW.decision_reason,
           NEW.retracted_at, NEW.closed_at)
          IS DISTINCT FROM
          (OLD.id, OLD.market_id, OLD.judgement_version, OLD.user_id, OLD.status,
           OLD.submitted_at, OLD.decided_by, OLD.decided_at, OLD.decision_reason,
           OLD.retracted_at, OLD.closed_at) THEN
      RAISE EXCEPTION 'dispute % of market % is emptied by its retention alone: its links and its reason, nothing else',
        OLD.id, OLD.market_id
        USING ERRCODE = 'integrity_constraint_violation';
    END IF;
    RETURN NEW;
  END IF;
  IF NEW.purged_at IS DISTINCT FROM OLD.purged_at
     OR NOT ((OLD.status = 'pending'
              AND NEW.status IN ('dismissed', 'accepted', 'retracted', 'closed_by_correction'))
             OR (OLD.status = 'accepted' AND NEW.status = 'pending' AND OLD.purged_at IS NULL)) THEN
    RAISE EXCEPTION 'dispute % of market % moves only from pending to dismissed, accepted, retracted or closed_by_correction, or from accepted back to pending',
      OLD.id, OLD.market_id
      USING ERRCODE = 'integrity_constraint_violation';
  END IF;
  IF (NEW.id, NEW.market_id, NEW.judgement_version, NEW.user_id, NEW.links, NEW.reason,
      NEW.submitted_at)
     IS DISTINCT FROM
     (OLD.id, OLD.market_id, OLD.judgement_version, OLD.user_id, OLD.links, OLD.reason,
      OLD.submitted_at) THEN
    RAISE EXCEPTION 'dispute % of market % keeps what its submission recorded', OLD.id,
      OLD.market_id
      USING ERRCODE = 'integrity_constraint_violation';
  END IF;
  RETURN NEW;
END;
$$;
